import { defineAsyncComponent, defineComponent, h } from 'vue'
import type { Component } from 'vue'
import type { ThemeData } from '~/interfaces'
import { useThemeData } from '~/composables/useThemeData'

/**
 * One variant of a region: bundled with the region when the build's theme uses it, else loaded on demand.
 *
 * @remarks
 * `#micelio/regions/<region>.mjs` lists them, generated by `regionVariantsModule` in `modules/theme/layout/variants.ts`.
 */
export type RegionVariant = { component: Component } | { load: () => Promise<{ default: Component }> }

/**
 * The component of a layout region: it renders the variant the active theme chose, at runtime (ADR 0009, #402).
 *
 * @remarks
 * The build's theme's variant is imported with the region, so the default theme's pages load what they did when the
 * variant was fixed at build time. Any other variant is its own chunk, loaded with `defineAsyncComponent`: the server
 * renders it and the client hydrates it. The variant comes from `useThemeData().layout`; an unknown name falls back to
 * the first entry, which is the region's default. Every attribute and listener passes through. `T` is the first
 * variant's type, which the variants of a region share, so call sites keep their prop types.
 *
 * @param variants - One per variant, by its name in `theme.json`, in the order of `REGION_VARIANTS`.
 */
export function defineRegion<T>(region: keyof ThemeData['layout'], name: string, variants: Record<string, RegionVariant>): T {
  const views = Object.fromEntries(Object.entries(variants).map(([variant, entry]) => [variant, 'component' in entry ? entry.component : defineAsyncComponent(entry.load)]))
  const fallback = Object.values(views)[0]!
  const component = defineComponent({
    name,
    inheritAttrs: false,
    setup(_props, { attrs }) {
      const view = views[useThemeData().layout[region]] ?? fallback
      return () => h(view, { ...attrs })
    },
  })
  return component as unknown as T
}
